package com.example.demo;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
class Livre {
  @Id Long id;
  String titre;
  protected Livre() {}
  Livre(Long id, String titre) { this.id = id; this.titre = titre; }
}

package com.example.demo;

import org.springframework.data.repository.CrudRepository;

interface LivreRepository extends CrudRepository<Livre, Long> {}

package com.example.demo;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
class AtelierController {
  private final LivreRepository livres;
  AtelierController(LivreRepository livres) { this.livres = livres; }
  @GetMapping("/livres/compter") long compter() { return livres.count(); }
}
